#include "digitor/plugin_performance_readiness.hpp"
#include <iostream>
int main(){using namespace digitor;PluginPerformanceBudget b;PluginPerformanceSample s; s.plugin_id="com.digitor.blur";s.version="1.0.0";s.package_sha256=std::string(64,'a');s.surface=PluginPerformanceSurface::preview;s.cold_compile_ms=120;s.warm_pipeline_ms=12;s.average_frame_ms=8;s.p95_frame_ms=12;s.peak_transient_bytes=64ull*1024ull*1024ull;s.cache_hits=99;s.cache_misses=1;auto ok=evaluate_plugin_performance(b,s);if(ok.decision!=PluginPerformanceDecision::ready||!ok.cache_ready)return 1;s.cache_hits=0;s.cache_misses=10;auto warm=evaluate_plugin_performance(b,s);if(warm.decision!=PluginPerformanceDecision::warmup_required)return 2;s.cache_hits=99;s.cache_misses=1;s.p95_frame_ms=40;auto slow=evaluate_plugin_performance(b,s);if(slow.decision!=PluginPerformanceDecision::budget_exceeded)return 3;s.p95_frame_ms=12;s.preview_export_contract_match=false;auto mismatch=evaluate_plugin_performance(b,s);if(mismatch.decision!=PluginPerformanceDecision::budget_exceeded)return 4;std::cout<<"PLUGIN_PERFORMANCE_READINESS=1\nPIPELINE_WARMUP_REQUIRED=1\nCACHE_HIT_GUARD=1\nPREVIEW_EXPORT_CONTRACT_MATCH=1\nMAIN_RENDERING_FEATURES_CHANGED=0\n";return 0;}
